class.description:
Runs the GDScript parser on source code and returns the resulting syntax tree as plain [Dictionary] and [Array] values. Only the parser runs: types are not resolved and no other scripts or resources are loaded.
[codeblock]
var tree = GDScriptSyntax.parse(FileAccess.get_file_as_string("res://player.gd"), "res://player.gd")
if tree.ok:
	print(tree["class"].extends_class)
	for function in tree["class"].functions:
		for call in function.calls:
			print(call.name, " ", call.args.size())
[/codeblock]
